import assert from 'node:assert/strict';
import { createShop } from './src/inventory-reservations/index.mjs';
import { createClient } from './src/retry-idempotency/client.mjs';
import { Ledger } from './src/atomic-ledger/ledger.mjs';

const shop = createShop({ t: { x: 10, y: 1 }, u: { x: 5 } });
const original = { tenant: 't', requestId: 'same', items: [{ sku: 'x', quantity: 2 }, { sku: 'x', quantity: 3 }] };
const receipt = shop.reserve(original);
assert.deepEqual(receipt.items, [{ sku: 'x', quantity: 5 }]);
receipt.items[0].quantity = 99;
original.items[0].quantity = 99;
assert.deepEqual(shop.reserve({ tenant: 't', requestId: 'same', items: [{ sku: 'x', quantity: 5 }] }).items, [{ sku: 'x', quantity: 5 }]);
shop.reserve({ tenant: 'u', requestId: 'same', items: [{ sku: 'x', quantity: 1 }] });
assert.equal(shop.stock('t', 'x'), 5);
assert.equal(shop.stock('u', 'x'), 4);
assert.throws(() => shop.reserve({ tenant: 't', requestId: 'bad', items: [{ sku: 'x', quantity: 2 }, { sku: 'y', quantity: 1 }] }));
assert.equal(shop.stock('t', 'x'), 5);
shop.reserve({ tenant: 't', requestId: 'bad', items: [{ sku: 'x', quantity: 1 }] });

const seen = []; const sleeps = []; let n = 0, generated = 0;
const request = createClient({ transport: async req => { seen.push(req); return { status: ++n < 3 ? 503 : 200, headers: n === 1 ? { 'Retry-After': '2' } : {} }; }, sleep: async ms => sleeps.push(ms), keyFactory: () => `k${++generated}`, baseMs: 25 });
assert.equal((await request({ method: 'POST', url: '/', headers: { Accept: 'application/json' } })).status, 200);
assert.deepEqual(seen.map(req => req.headers['idempotency-key']), ['k1', 'k1', 'k1']);
assert.deepEqual(sleeps, [2000, 50]);
await request({ method: 'POST', url: '/', headers: { 'Idempotency-Key': 'provided' } });
assert.equal(seen.at(-1).headers['Idempotency-Key'], 'provided');
assert.equal(generated, 1);

const ledger = new Ledger({ a: 50, b: 0 });
assert.deepEqual(ledger.applyBatch([{ id: 'x', from: 'a', to: 'b', amount: 10 }, { id: 'x', from: 'a', to: 'b', amount: 10 }]), { a: 40, b: 10 });
assert.throws(() => ledger.applyBatch([{ id: 'y', from: 'a', to: 'b', amount: 5 }, { id: 'z', from: 'a', to: 'b', amount: 100 }]));
assert.deepEqual(ledger.snapshot(), { a: 40, b: 10 });
assert.deepEqual(ledger.applyBatch([{ id: 'y', from: 'a', to: 'b', amount: 5 }]), { a: 35, b: 15 });
console.log('Contract smoke checks passed.');
EOF

