export function delayFor(response, attempt, baseMs) {
  const retryAfter = response.headers?.get?.('retry-after')
    ?? Object.entries(response.headers ?? {}).find(([name]) => name.toLowerCase() === 'retry-after')?.[1];
  const seconds = typeof retryAfter === 'number'
    ? retryAfter
    : typeof retryAfter === 'string' && retryAfter.trim() !== '' ? Number(retryAfter) : NaN;
  if (Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;
  return baseMs * 2 ** (attempt - 1);
}
export function shouldRetry(response) {
  return response.status === 429 || (response.status >= 500 && response.status < 600);
}
